1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		spans map[string]*span
93	
94		// Discovery target snapshot; same lock so reloads swap one immutable
95		// snapshot pointer and queries always read a consistent generation.
96		discovery *discoverySnapshot
97	}
98	
99	func newMetricStore() *metricStore {
100		return &metricStore{
101			series:             make(map[string]*series),
102			rules:              make(map[string]*alertRule),
103			silences:           make(map[string]*silence),
104			inhibitions:        make(map[string]*inhibitRule),
105			notificationRoutes: make(map[string]*notificationRoute),
106			slos:               make(map[string]*sloDefinition),
107			logs:               make(map[string]*logEntry),
108			spans:              make(map[string]*span),
109			discovery:          emptyDiscoverySnapshot(),
110		}
111	}
112	
113	// validatedSample is a sample that passed all format and value checks.
114	type validatedSample struct {
115		key     string
116		name    string
117		typ     string
118		labels  map[string]string
119		value   float64
120		buckets []float64 // non-nil for histograms
121		ts      time.Time
122	}
123	
124	// checkAndApply validates the batch against the current state (and against
125	// itself) and then commits it in array order. A false result signals a type or
126	// bucket-boundary conflict; in that case no state is mutated.
127	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
128		s.mu.Lock()
129		defer s.mu.Unlock()
130	
131		// First pass: conflict detection against committed state and earlier
132		// samples in the same batch.
133		resolved := make(map[string]*series, len(batch))
134		for _, sm := range batch {
135			existing, ok := s.series[sm.key]
136			if !ok {
137				if shadow, seen := resolved[sm.key]; seen {
138					existing, ok = shadow, true
139				}
140			}
141			if ok {
142				if existing.typ != sm.typ {
143					return false
144				}
145				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
146					return false
147				}
148				resolved[sm.key] = existing
149				continue
150			}
151			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
152		}
153	
154		// Second pass: commit in order.
155		for _, sm := range batch {
156			cur, ok := s.series[sm.key]
157			if !ok {
158				cur = &series{
159					name:         sm.name,
160					typ:          sm.typ,
161					labels:       sm.labels,
162					bucketBounds: append([]float64(nil), sm.buckets...),
163				}
164				if sm.typ == "histogram" {
165					cur.bucketCounts = make([]int64, len(sm.buckets))
166				}
167				s.series[sm.key] = cur
168			}
169			switch sm.typ {
170			case "counter":
171				cur.value += sm.value
172			case "gauge":
173				cur.value = sm.value
174			case "histogram":
175				cur.count++
176				cur.sum += sm.value
177				for i, bound := range cur.bucketBounds {
178					if sm.value <= bound {
179						cur.bucketCounts[i]++
180					}
181				}
182			}
183			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
184		}
185		return true
186	}
187	
188	type seriesOutput struct {
189		Name    string            `json:"name"`
190		Type    string            `json:"type"`
191		Labels  map[string]string `json:"labels"`
192		Value   *float64          `json:"value,omitempty"`
193		Count   *int64            `json:"count,omitempty"`
194		Sum     *float64          `json:"sum,omitempty"`
195		Buckets []bucketOutput    `json:"buckets,omitempty"`
196	}
197	
198	type bucketOutput struct {
199		LE    float64 `json:"le"`
200		Count int64   `json:"count"`
201	}
202	
203	// query returns matching series as ready-to-encode outputs. A series matches
204	// when its name equals name exactly and it contains every selector label.
205	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
206		s.mu.RLock()
207		defer s.mu.RUnlock()
208	
209		out := make([]seriesOutput, 0)
210		for _, cur := range s.series {
211			if cur.name != name {
212				continue
213			}
214			matched := true
215			for k, v := range selector {
216				got, ok := cur.labels[k]
217				if !ok || got != v {
218					matched = false
219					break
220				}
221			}
222			if !matched {
223				continue
224			}
225			item := seriesOutput{
226				Name:   cur.name,
227				Type:   cur.typ,
228				Labels: copyLabels(cur.labels),
229			}
230			switch cur.typ {
231			case "counter", "gauge":
232				v := cur.value
233				item.Value = &v
234			case "histogram":
235				c, sum := cur.count, cur.sum
236				item.Count = &c
237				item.Sum = &sum
238				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
239				for i, bound := range cur.bucketBounds {
240					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
241				}
242			}
243			out = append(out, item)
244		}
245	
246		sort.Slice(out, func(i, j int) bool {
247			return compareLabels(out[i].Labels, out[j].Labels) < 0
248		})
249		return out
250	}
251	
252	// compareLabels imposes a normalized lexicographic order on full label sets:
253	// keys are sorted, then (key, value) pairs are compared element-wise, and a
254	// shorter pair list sorts first when it is a prefix of a longer one.
255	func compareLabels(a, b map[string]string) int {
256		ka := sortedKeys(a)
257		kb := sortedKeys(b)
258		n := len(ka)
259		if len(kb) < n {
260			n = len(kb)
261		}
262		for i := 0; i < n; i++ {
263			if ka[i] != kb[i] {
264				return strings.Compare(ka[i], kb[i])
265			}
266			if a[ka[i]] != b[kb[i]] {
267				return strings.Compare(a[ka[i]], b[kb[i]])
268			}
269		}
270		switch {
271		case len(ka) < len(kb):
272			return -1
273		case len(ka) > len(kb):
274			return 1
275		default:
276			return 0
277		}
278	}
279	
280	func sortedKeys(m map[string]string) []string {
281		keys := make([]string, 0, len(m))
282		for k := range m {
283			keys = append(keys, k)
284		}
285		sort.Strings(keys)
286		return keys
287	}
288	
289	func copyLabels(in map[string]string) map[string]string {
290		out := make(map[string]string, len(in))
291		for k, v := range in {
292			out[k] = v
293		}
294		return out
295	}
296	
297	// seriesKey builds a collision-free identity from name + unordered labels.
298	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
299	// so length-prefixed values remove any ambiguity from arbitrary label values.
300	func seriesKey(name string, labels map[string]string) string {
301		var b strings.Builder
302		b.WriteString(name)
303		for _, k := range sortedKeys(labels) {
304			b.WriteByte(0)
305			b.WriteString(k)
306			b.WriteByte(0)
307			v := labels[k]
308			b.WriteString(strconv.Itoa(len(v)))
309			b.WriteByte(0)
310			b.WriteString(v)
311		}
312		return b.String()
313	}
314	
315	func equalBuckets(a, b []float64) bool {
316		if len(a) != len(b) {
317			return false
318		}
319		for i := range a {
320			if a[i] != b[i] {
321				return false
322			}
323		}
324		return true
325	}
326	
327	// Handler returns the HTTP surface served by SignalWatch.
328	func Handler() http.Handler {
329		return newHandler(newTenantRegistry())
330	}
331	
332	func newHandler(registry *tenantRegistry) http.Handler {
333		mux := http.NewServeMux()
334	
335		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
336			if r.Method != http.MethodGet {
337				w.Header().Set("Allow", http.MethodGet)
338				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
339				return
340			}
341			w.Header().Set("Content-Type", "application/json; charset=utf-8")
342			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
343		})
344	
345		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
346			switch r.Method {
347			case http.MethodGet:
348				handleMetricsGet(w, r)
349			case http.MethodPost:
350				handleMetricsPost(w, r)
351			default:
352				w.Header().Set("Allow", "GET, POST")
353				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
354			}
355		})
356	
357		registerAlertHandlers(mux)
358		registerSilenceHandlers(mux)
359		registerInhibitHandlers(mux)
360		registerNotificationRouteHandlers(mux)
361		registerSLOHandlers(mux)
362		registerQueryHandler(mux)
363		registerMetricRangeHandler(mux)
364		registerQueryRangeHandler(mux)
365		registerLogHandlers(mux)
366		registerSpanHandlers(mux)
367		registerDiscoveryTargetHandlers(mux)
368	
369		return withTenants(mux, registry)
370	}
371	
372	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
373		// All samples in the request share this single receive instant: it is the
374		// default timestamp and the anchor for the accepted timestamp window.
375		receivedAt := time.Now()
376		store := tenantStore(r)
377		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
378		if err != nil || mediaType != "application/json" {
379			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
380			return
381		}
382	
383		body, err := io.ReadAll(r.Body)
384		if err != nil {
385			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
386			return
387		}
388	
389		batch, code := decodeMetricsBatch(body, receivedAt)
390		if code != "" {
391			writeAPIError(w, code, http.StatusBadRequest)
392			return
393		}
394	
395		if !store.checkAndApply(batch) {
396			writeAPIError(w, "metric_conflict", http.StatusConflict)
397			return
398		}
399	
400		w.Header().Set("Content-Type", "application/json; charset=utf-8")
401		w.WriteHeader(http.StatusAccepted)
402		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
403	}
404	
405	type metricsEnvelope struct {
406		Samples *[]json.RawMessage `json:"samples"`
407	}
408	
409	type rawSample struct {
410		Name      *string            `json:"name"`
411		Type      *string            `json:"type"`
412		Labels    *map[string]string `json:"labels"`
413		Value     *float64           `json:"value"`
414		Buckets   *[]float64         `json:"buckets"`
415		Timestamp *string            `json:"timestamp"`
416	}
417	
418	// decodeMetricsBatch performs every format and value check, including the
419	// optional per-sample timestamp. It never returns a partially validated
420	// batch. The returned error code is empty on success.
421	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
422		var env metricsEnvelope
423		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
424			return nil, "invalid_metrics"
425		}
426	
427		batch := make([]validatedSample, 0, len(*env.Samples))
428		for _, raw := range *env.Samples {
429			var sm rawSample
430			if !strictDecode(raw, &sm) {
431				return nil, "invalid_metrics"
432			}
433			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
434				return nil, "invalid_metrics"
435			}
436			name, typ := *sm.Name, *sm.Type
437			if !identPattern.MatchString(name) {
438				return nil, "invalid_metrics"
439			}
440			if typ != "counter" && typ != "gauge" && typ != "histogram" {
441				return nil, "invalid_metrics"
442			}
443			labels := *sm.Labels
444			if labels == nil {
445				return nil, "invalid_metrics" // explicit null labels
446			}
447			for k := range labels {
448				if !identPattern.MatchString(k) {
449					return nil, "invalid_metrics"
450				}
451			}
452			value := *sm.Value
453			if math.IsNaN(value) || math.IsInf(value, 0) {
454				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
455			}
456			if typ == "counter" && value < 0 {
457				return nil, "invalid_metrics"
458			}
459	
460			var buckets []float64
461			if typ == "histogram" {
462				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
463					return nil, "invalid_metrics"
464				}
465				buckets = append([]float64(nil), (*sm.Buckets)...)
466			} else if sm.Buckets != nil {
467				return nil, "invalid_metrics" // buckets only valid on histograms
468			}
469	
470			// The timestamp is optional; every sample without one shares the
471			// request's receive instant.
472			ts := receivedAt
473			if sm.Timestamp != nil {
474				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
475				if err != nil {
476					return nil, "invalid_metrics"
477				}
478				ts = parsed
479			}
480			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
481				return nil, "metric_timestamp_out_of_range"
482			}
483	
484			batch = append(batch, validatedSample{
485				key:     seriesKey(name, labels),
486				name:    name,
487				typ:     typ,
488				labels:  copyLabels(labels),
489				value:   value,
490				buckets: buckets,
491				ts:      ts,
492			})
493		}
494		return batch, ""
495	}
496	
497	func validBuckets(buckets []float64) bool {
498		if len(buckets) == 0 {
499			return false
500		}
501		prev := math.Inf(-1)
502		for _, b := range buckets {
503			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
504				return false
505			}
506			prev = b
507		}
508		return true
509	}
510	
511	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
512	// values and non-object payloads for struct targets.
513	func strictDecode(data []byte, target any) bool {
514		dec := json.NewDecoder(bytes.NewReader(data))
515		dec.DisallowUnknownFields()
516		if err := dec.Decode(target); err != nil {
517			return false
518		}
519		var extra json.RawMessage
520		if err := dec.Decode(&extra); err != io.EOF {
521			return false
522		}
523		return true
524	}
525	
526	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
527		store := tenantStore(r)
528		values, err := url.ParseQuery(r.URL.RawQuery)
529		if err != nil {
530			writeAPIError(w, "invalid_query", http.StatusBadRequest)
531			return
532		}
533	
534		names := values["name"]
535		if len(names) == 0 || !identPattern.MatchString(names[0]) {
536			writeAPIError(w, "invalid_query", http.StatusBadRequest)
537			return
538		}
539	
540		selector := make(map[string]string)
541		for key, vals := range values {
542			if !strings.HasPrefix(key, "label.") {
543				continue
544			}
545			labelKey := strings.TrimPrefix(key, "label.")
546			if !identPattern.MatchString(labelKey) {
547				writeAPIError(w, "invalid_query", http.StatusBadRequest)
548				return
549			}
550			for _, v := range vals[1:] {
551				if v != vals[0] {
552					writeAPIError(w, "invalid_query", http.StatusBadRequest)
553					return
554				}
555			}
556			selector[labelKey] = vals[0]
557		}
558	
559		seriesList := store.query(names[0], selector)
560		w.Header().Set("Content-Type", "application/json; charset=utf-8")
561		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
562	}
563	
564	func writeAPIError(w http.ResponseWriter, code string, status int) {
565		w.Header().Set("Content-Type", "application/json; charset=utf-8")
566		w.WriteHeader(status)
567		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
568	}
