3	import (
4		"encoding/json"
5		"io"
6		"maps"
7		"mime"
8		"net/http"
9		"net/url"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	const (
16		spansPath            = "/api/v1/spans"
17		tracesCollectionPath = "/api/v1/traces"
18		tracesPrefix         = tracesCollectionPath + "/"
19	)
20	
21	var spanStatuses = map[string]bool{
22		"unset": true,
23		"ok":    true,
24		"error": true,
25	}
26	
27	// span is one committed trace span. Spans are immutable once stored.
28	type span struct {
29		traceID      string
30		spanID       string
31		parentSpanID string // "" when parent_span_id is null
32		service      string
33		name         string
34		startTime    time.Time
35		endTime      time.Time
36		status       string
37		attributes   map[string]string
38	}
39	
40	// sameContent reports whether two spans with the same (trace_id, span_id)
41	// carry the same content, making the later one a replay rather than a
42	// conflict. Time instants compare regardless of the submitted zone.
43	func (sp *span) sameContent(other *span) bool {
44		return sp.traceID == other.traceID &&
45			sp.spanID == other.spanID &&
46			sp.parentSpanID == other.parentSpanID &&
47			sp.service == other.service &&
48			sp.name == other.name &&
49			sp.startTime.Equal(other.startTime) &&
50			sp.endTime.Equal(other.endTime) &&
51			sp.status == other.status &&
52			maps.Equal(sp.attributes, other.attributes)
53	}
54	
55	// spanKey builds the tenant-unique identity of a span from trace and span id.
56	// Both ids are lowercase hex of fixed length, so a NUL separator is
57	// unambiguous.
58	func spanKey(traceID, spanID string) string {
59		return traceID + "\x00" + spanID
60	}
61	
62	// checkAndApplySpans validates the batch against committed state (and against
63	// itself) and then commits it in array order. A false result signals a content
64	// conflict on a repeated span; in that case no state is mutated. Replays —
65	// repeats of a (trace_id, span_id) with identical content — are counted but do
66	// not mutate state.
67	func (s *metricStore) checkAndApplySpans(batch []*span) (accepted, replayed int, ok bool) {
68		s.mu.Lock()
69		defer s.mu.Unlock()
70	
71		// First pass: conflict detection against committed spans and earlier
72		// spans in the same batch.
73		seen := make(map[string]*span, len(batch))
74		for _, sp := range batch {
75			key := spanKey(sp.traceID, sp.spanID)
76			if prev, dup := seen[key]; dup {
77				if !prev.sameContent(sp) {
78					return 0, 0, false
79				}
80				continue
81			}
82			if existing, committed := s.spans[key]; committed && !existing.sameContent(sp) {
83				return 0, 0, false
84			}
85			seen[key] = sp
86		}
87	
88		// Second pass: commit in array order.
89		for _, sp := range batch {
90			key := spanKey(sp.traceID, sp.spanID)
91			if _, exists := s.spans[key]; exists {
92				replayed++
93				continue
94			}
95			s.spans[key] = sp
96			accepted++
97		}
98		return accepted, replayed, true
99	}
100	
101	// traceSnapshot is one consistent read of a trace's spans together with the
102	// retained logs carrying the same trace id.
103	type traceSnapshot struct {
104		spans []*span
105		logs  []*logEntry
106	}
107	
108	// getTrace returns the spans of traceID and the currently retained logs with
109	// that trace id. The found flag is false only when no span is stored; logs
110	// alone never create a trace.
111	func (s *metricStore) getTrace(traceID string) (traceSnapshot, bool) {
112		s.mu.RLock()
113		defer s.mu.RUnlock()
114	
115		var snap traceSnapshot
116		for _, sp := range s.spans {
117			if sp.traceID == traceID {
118				snap.spans = append(snap.spans, sp)
119			}
120		}
121		if len(snap.spans) == 0 {
122			return traceSnapshot{}, false
123		}
124		for _, e := range s.logs {
125			if e.traceID == traceID {
126				snap.logs = append(snap.logs, e)
127			}
128		}
129		sort.Slice(snap.spans, func(i, j int) bool {
130			a, b := snap.spans[i], snap.spans[j]
131			if !a.startTime.Equal(b.startTime) {
132				return a.startTime.Before(b.startTime)
133			}
134			return a.spanID < b.spanID
135		})
136		sort.Slice(snap.logs, func(i, j int) bool {
137			a, b := snap.logs[i], snap.logs[j]
138			if !a.timestamp.Equal(b.timestamp) {
139				return a.timestamp.Before(b.timestamp)
140			}
141			return a.id < b.id
142		})
143		return snap, true
144	}
145	
146	// ---- JSON wire shapes ------------------------------------------------------
147	
148	type spansEnvelope struct {
149		Spans *[]json.RawMessage `json:"spans"`
150	}
151	
152	type rawSpan struct {
153		TraceID      *string         `json:"trace_id"`
154		SpanID       *string         `json:"span_id"`
155		ParentSpanID json.RawMessage `json:"parent_span_id"`
156		Service      *string         `json:"service"`
157		Name         *string         `json:"name"`
158		StartTime    *string         `json:"start_time"`
159		EndTime      *string         `json:"end_time"`
160		Status       *string         `json:"status"`
161		Attributes   json.RawMessage `json:"attributes"`
162	}
163	
164	type spanJSON struct {
165		TraceID      string            `json:"trace_id"`
166		SpanID       string            `json:"span_id"`
167		ParentSpanID *string           `json:"parent_span_id"`
168		Service      string            `json:"service"`
169		Name         string            `json:"name"`
170		StartTime    string            `json:"start_time"`
171		EndTime      string            `json:"end_time"`
172		Status       string            `json:"status"`
173		Attributes   map[string]string `json:"attributes"`
174	}
175	
176	func (sp *span) wireJSON() spanJSON {
177		out := spanJSON{
178			TraceID:    sp.traceID,
179			SpanID:     sp.spanID,
180			Service:    sp.service,
181			Name:       sp.name,
182			StartTime:  sp.startTime.UTC().Format(time.RFC3339Nano),
183			EndTime:    sp.endTime.UTC().Format(time.RFC3339Nano),
184			Status:     sp.status,
185			Attributes: copyLabels(sp.attributes),
186		}
187		if sp.parentSpanID != "" {
188			parent := sp.parentSpanID
189			out.ParentSpanID = &parent
190		}
191		return out
192	}
193	
194	// decodeSpanBatch performs every format and value check. It never returns a
195	// partially validated batch.
196	func decodeSpanBatch(body []byte) ([]*span, bool) {
197		var env spansEnvelope
198		if !strictDecode(body, &env) || env.Spans == nil || len(*env.Spans) == 0 {
199			return nil, false
200		}
201	
202		batch := make([]*span, 0, len(*env.Spans))
203		for _, raw := range *env.Spans {
204			var rs rawSpan
205			if !strictDecode(raw, &rs) {
206				return nil, false
207			}
208			if rs.TraceID == nil || rs.SpanID == nil || len(rs.ParentSpanID) == 0 ||
209				rs.Service == nil || rs.Name == nil || rs.StartTime == nil ||
210				rs.EndTime == nil || rs.Status == nil || rs.Attributes == nil {
211				return nil, false
212			}
213			traceID := *rs.TraceID
214			if !validTraceID(traceID) {
215				return nil, false
216			}
217			spanID := *rs.SpanID
218			if !validSpanID(spanID) {
219				return nil, false
220			}
221			// parent_span_id is exactly null or a span-id string; a missing field
222			// was rejected above. The parent span itself may arrive later.
223			var parentPtr *string
224			if err := json.Unmarshal(rs.ParentSpanID, &parentPtr); err != nil {
225				return nil, false
226			}
227			parentSpanID := ""
228			if parentPtr != nil {
229				parentSpanID = *parentPtr
230				if !validSpanID(parentSpanID) || parentSpanID == spanID {
231					return nil, false
232				}
233			}
234			service := *rs.Service
235			name := *rs.Name
236			if service == "" || name == "" {
237				return nil, false
238			}
239			startTime, err := time.Parse(time.RFC3339Nano, *rs.StartTime)
240			if err != nil {
241				return nil, false
242			}
243			endTime, err := time.Parse(time.RFC3339Nano, *rs.EndTime)
244			if err != nil {
245				return nil, false
246			}
247			if endTime.Before(startTime) {
248				return nil, false
249			}
250			status := *rs.Status
251			if !spanStatuses[status] {
252				return nil, false
253			}
254			// attributes must be a JSON object of string values. RawMessage keeps
255			// explicit nulls visible: encoding/json would otherwise fold a null
256			// value into the empty string, and a whole-document null into a nil
257			// map; both are illegal here.
258			var rawAttrs map[string]json.RawMessage
259			if err := json.Unmarshal(rs.Attributes, &rawAttrs); err != nil || rawAttrs == nil {
260				return nil, false
261			}
262			attributes := make(map[string]string, len(rawAttrs))
263			for k, rawVal := range rawAttrs {
264				if !identPattern.MatchString(k) {
265					return nil, false
266				}
267				var value *string
268				if err := json.Unmarshal(rawVal, &value); err != nil || value == nil {
269					return nil, false
270				}
271				attributes[k] = *value
272			}
273			batch = append(batch, &span{
274				traceID:      traceID,
275				spanID:       spanID,
276				parentSpanID: parentSpanID,
277				service:      service,
278				name:         name,
279				startTime:    startTime,
280				endTime:      endTime,
281				status:       status,
282				attributes:   attributes,
283			})
284		}
285		return batch, true
286	}
287	
288	// validSpanID reports whether id is exactly 16 lowercase hex characters.
289	func validSpanID(id string) bool {
290		if len(id) != 16 {
291			return false
292		}
293		for i := 0; i < len(id); i++ {
294			c := id[i]
295			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
296				return false
297			}
298		}
299		return true
300	}
301	
302	// ---- HTTP handlers ---------------------------------------------------------
303	
304	func registerSpanHandlers(mux *http.ServeMux) {
305		mux.HandleFunc(spansPath, func(w http.ResponseWriter, r *http.Request) {
306			if r.Method != http.MethodPost {
307				w.Header().Set("Allow", http.MethodPost)
308				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
309				return
310			}
311			handleSpansPost(w, r)
312		})
313	
314		// The trace collection has no list endpoint; answer the exact collection
315		// path with the baseline 404 instead of letting the subtree pattern issue
316		// its trailing-slash redirect.
317		mux.HandleFunc(tracesCollectionPath, func(w http.ResponseWriter, r *http.Request) {
318			http.NotFound(w, r)
319		})
320	
321		mux.HandleFunc(tracesPrefix, func(w http.ResponseWriter, r *http.Request) {
322			if r.Method != http.MethodGet {
323				w.Header().Set("Allow", http.MethodGet)
324				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
325				return
326			}
327			handleTraceGet(w, r)
328		})
329	}
330	
331	func handleSpansPost(w http.ResponseWriter, r *http.Request) {
332		store := tenantStore(r)
333		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
334		if err != nil || mediaType != "application/json" {
335			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
336			return
337		}
338	
339		body, err := io.ReadAll(r.Body)
340		if err != nil {
341			writeAPIError(w, "invalid_spans", http.StatusBadRequest)
342			return
343		}
344	
345		batch, ok := decodeSpanBatch(body)
346		if !ok {
347			writeAPIError(w, "invalid_spans", http.StatusBadRequest)
348			return
349		}
350	
351		accepted, replayed, applied := store.checkAndApplySpans(batch)
352		if !applied {
353			writeAPIError(w, "span_conflict", http.StatusConflict)
354			return
355		}
356	
357		writeJSON(w, http.StatusAccepted, map[string]int{"accepted": accepted, "replayed": replayed})
358	}
359	
360	func handleTraceGet(w http.ResponseWriter, r *http.Request) {
361		traceID := strings.TrimPrefix(r.URL.Path, tracesPrefix)
362		if traceID == "" || strings.Contains(traceID, "/") || !validTraceID(traceID) {
363			writeAPIError(w, "invalid_trace_id", http.StatusBadRequest)
364			return
365		}
366		// The trace detail endpoint defines no query vocabulary, so any parameter
367		// is an invalid query.
368		values, err := url.ParseQuery(r.URL.RawQuery)
369		if err != nil || len(values) != 0 {
370			writeAPIError(w, "invalid_trace_query", http.StatusBadRequest)
371			return
372		}
373	
374		snap, found := tenantStore(r).getTrace(traceID)
375		if !found {
376			writeAPIError(w, "trace_not_found", http.StatusNotFound)
377			return
378		}
379	
380		spans := make([]spanJSON, 0, len(snap.spans))
381		for _, sp := range snap.spans {
382			spans = append(spans, sp.wireJSON())
383		}
384		logs := make([]logEntryJSON, 0, len(snap.logs))
385		for _, e := range snap.logs {
386			logs = append(logs, e.wireJSON())
387		}
388		writeJSON(w, http.StatusOK, map[string]any{
389			"trace_id": traceID,
390			"spans":    spans,
391			"logs":     logs,
392		})
393	}
